public class TextRuleTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.function.Supplier<Object> call) {
        Object actual;
        try {
            actual = call.get();
        } catch (Throwable t) {
            actual = "threw " + t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    static void done() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    public static void main(String[] args) {
        checkCall("TRIM", "hi there", () -> TextRule.TRIM.apply("  hi there  "));
        checkCall("COLLAPSE_SPACES", "a b c", () -> TextRule.COLLAPSE_SPACES.apply("a   b  c"));
        checkCall("COLLAPSE_SPACES leaves single spaces", "a b", () -> TextRule.COLLAPSE_SPACES.apply("a b"));
        checkCall("TITLE_CASE fixes odd capitals", "Hello Wide World",
                () -> TextRule.TITLE_CASE.apply("hELLO wide wORLD"));
        checkCall("TITLE_CASE keeps double spaces", "A  B", () -> TextRule.TITLE_CASE.apply("a  b"));
        checkCall("STRIP_VOWELS", "Btfl Dy", () -> TextRule.STRIP_VOWELS.apply("Beautiful Day"));
        checkCall("STRIP_VOWELS on all vowels", "", () -> TextRule.STRIP_VOWELS.apply("AEIOUaeiou"));

        checkCall("applyAll runs rules in order", "Hello Wide World",
                () -> TextRule.applyAll("  hELLO   wide  world  ",
                        TextRule.TRIM, TextRule.COLLAPSE_SPACES, TextRule.TITLE_CASE));
        checkCall("order matters", "Hll Wrld",
                () -> TextRule.applyAll("hello world", TextRule.TITLE_CASE, TextRule.STRIP_VOWELS));
        checkCall("no rules leaves the text alone", "as is", () -> TextRule.applyAll("as is"));
        done();
    }
}

