/**
 * TASK: Complete the TextRule enum. Each constant needs its own body that
 * implements the abstract apply method.
 *
 * - TRIM removes leading and trailing spaces: "  hi  " -> "hi"
 * - COLLAPSE_SPACES turns every run of two or more spaces into one:
 *   "a   b  c" -> "a b c"
 * - TITLE_CASE upper-cases the first letter of every word and lower-cases the
 *   rest. A character starts a word when it is at index 0 or the character
 *   before it is a space, so "hELLO wide" -> "Hello Wide" and "a  b" -> "A  B".
 * - STRIP_VOWELS deletes every a, e, i, o and u in either case:
 *   "Beautiful Day" -> "Btfl Dy"
 *
 * applyAll(input, rules) runs the rules over the input in the order given and
 * returns the result. With no rules it returns the input unchanged.
 *
 * Example: applyAll("  hELLO   wide  world  ", TRIM, COLLAPSE_SPACES, TITLE_CASE)
 *          -> "Hello Wide World"
 */
public enum TextRule {

    TRIM {
        @Override
        public String apply(String input) {
            return input.trim();
        }
    },
    COLLAPSE_SPACES {
        @Override
        public String apply(String input) {
            return input.replaceAll(" +", " ");
        }
    },
    TITLE_CASE {
        @Override
        public String apply(String input) {
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < input.length(); i++) {
                char c = input.charAt(i);
                boolean startsWord = (i == 0) || (input.charAt(i - 1) == ' ');
                out.append(startsWord ? Character.toUpperCase(c) : Character.toLowerCase(c));
            }
            return out.toString();
        }
    },
    STRIP_VOWELS {
        @Override
        public String apply(String input) {
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < input.length(); i++) {
                char c = input.charAt(i);
                if ("aeiouAEIOU".indexOf(c) < 0) {
                    out.append(c);
                }
            }
            return out.toString();
        }
    };

    public abstract String apply(String input);

    public static String applyAll(String input, TextRule... rules) {
        String result = input;
        for (TextRule rule : rules) {
            result = rule.apply(result);
        }
        return result;
    }
}
